document.addEventListener('click',async e=>{const nav=e.target.closest('[data-nav]');if(nav){navigate(nav.dataset.nav);return;}const el=e.target.closest('[data-action]');if(el)try{await act(el.dataset.action,el);}catch(err){if(err.name!=='AbortError')toast(err instanceof SyntaxError?'El archivo o contenido no es un JSON válido.':err.message);el.disabled=false;} });
document.addEventListener('paste',async e=>{if(e.target.id!=='access-url')return;const value=e.clipboardData?.getData('text/plain')?.trim();if(!value)return;e.preventDefault();e.target.value=value;try{await connectAccessUrl(value);}catch(err){$('#access-error').textContent=err.message;}});
document.addEventListener('input',e=>{const t=e.target;if(t.id==='day-note'&&draft){draft.note=t.value;dirty=true;renderPreview();}if(t.dataset.massField&&draft){draft.masses.find(m=>m.id===t.closest('[data-mass]').dataset.mass)[t.dataset.massField]=t.value;dirty=true;renderPreview();}if(t.classList.contains('person-search')){const picker=t.closest('.picker');let visible=0;for(const row of picker.querySelectorAll('[data-search]')){row.hidden=!row.dataset.search.includes(normalize(t.value));if(!row.hidden)visible++;}picker.querySelector('.picker-empty').hidden=visible>0;}if(t.id==='people-search'){searchText=t.value;for(const card of document.querySelectorAll('.person-card'))card.hidden=!normalize(card.querySelector('strong').textContent).includes(normalize(searchText));}});
document.addEventListener('change',async e=>{const t=e.target;try{if(t.matches('[data-person-check]')&&draft){const m=draft.masses.find(x=>x.id===t.dataset.mass);if(!m)return;if(t.checked){if(!m.personIds.includes(t.dataset.personCheck))m.personIds.push(t.dataset.personCheck);}else m.personIds=m.personIds.filter(id=>id!==t.dataset.personCheck);dirty=true;updateMassSelection(m.id);}if(t.id==='reviewed'&&draft){draft.reviewed=t.checked;dirty=true;}if(t.id==='show-archived'){showArchived=t.checked;renderPeople();}if(t.id==='inapp-alert'){config.inAppAlerts=t.checked;await write('config',config);}if(t.id==='backup-file'&&t.files[0]){if(t.files[0].size>12000000)throw Error('El archivo es demasiado grande.');$('#backup-text').value=await t.files[0].text();}}catch(err){toast(err.message);}});
document.addEventListener('submit',async e=>{e.preventDefault();try{if(e.target.id==='person-form'){const form=e.target,name=form.elements.name.value.trim();if(!name)throw Error('Escribe el nombre.');const id=form.dataset.id||'p-'+uid();const existing=allPeople().find(p=>normalize(p.name)===normalize(name)&&p.id!==id&&!p.archived&&!p.mergedInto);if(existing)throw Error('Este nombre ya está en la lista. Puedes editar el existente.');const previous=allPeople().find(p=>p.id===id);change(state,'person',id,{...previous,id,name,active:form.elements.active.checked,archived:false,aliases:previous?.aliases||[]},previous?`Editar a ${name}`:`Añadir a ${name}`);if(await persist()){modal.close();render();toast('Nombre guardado.');}}
 if(e.target.id==='connection-form'){const f=e.target;const endpoint=f.elements.endpoint.value.trim();if(!/^https:\/\/script\.google\.com\/macros\/s\/[\w-]+\/exec$/.test(endpoint))throw Error('Usa el enlace de la aplicación web de Google terminado en /exec.');config={...config,endpoint,key:f.elements.key.value.trim(),device:f.elements.device.value.trim()};await write('config',config);rememberConnection();renderSettings();await doSync();}}catch(err){toast(err.message);}});
$('#sync').addEventListener('click',()=>doSync());modal.addEventListener('click',e=>{if(e.target===modal)modal.close();});window.addEventListener('online',()=>{status();if(config.endpoint)doSync(true);});document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible'&&config.endpoint)doSync(true);});setInterval(()=>{if(document.visibilityState==='visible'&&config.endpoint&&!modal.open)doSync(true);},60000);window.addEventListener('offline',status);window.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue='';}});
async function consumeAccess(){const token=new URLSearchParams(location.hash.slice(1)).get('conectar');if(!token)return false;try{const incoming=connectionFromToken(token);if(config.key&&config.key!==incoming.key&&dirty)throw Error('Guarda el día antes de cambiar el acceso privado.');config={...config,...incoming,device:config.device||'Mi iPhone'};await write('config',config);rememberConnection();return true;}catch(err){syncError=err.message;toast(err.message);return false;}finally{history.replaceState(null,'',location.pathname+location.search);}}
window.addEventListener('hashchange',async()=>{if(await consumeAccess())await doSync();});
async function init(){try{await openDB();state=await read('state')||emptyState();config=await read('config')||{};if(!await consumeAccess()&&config.endpoint&&config.key)rememberConnection();const requestedWeek=new URLSearchParams(location.search).get('week');if(requestedWeek&&/^\d{4}-\d{2}-\d{2}$/.test(requestedWeek)){selectedWeek=weekStart(requestedWeek);year=+requestedWeek.slice(0,4);month=+requestedWeek.slice(5,7)-1;}render();if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js',{scope:'./'}).catch(()=>toast('No se pudo preparar el modo sin conexión. Abre la app de nuevo con internet.'));navigator.storage?.persist?.().catch(()=>{});if(config.inAppAlerts!==false&&activePeople().length){const w=weekSummary(state,selectedWeek);if(w.unassigned.length)toast(`Sin misa esta semana: ${w.unassigned.map(p=>p.name).join(', ')}.`);}if(navigator.onLine&&config.endpoint)doSync();}catch(err){$('#main').innerHTML=heading('No pudimos abrir el almacenamiento','Revisa que el navegador permita guardar datos de esta app.')+`<div class="notice">${esc(err.message)}</div>`;}}
init();
